    "t": "OpenAI רוכשת את TBPN\n\nOpenAI קנתה את TBPN כדי להאיץ שיחות גלובליות סביב AI ולתמוך בתקשורת בלתי תלויה. הרכישה תעזור לחברה להרחיב את הדיאלוג שלה עם מפתחים, עסקים וקהילת הטק הרחבה יותר.",
